INSERT INTO "public"."fommenu" ("pk", "parentpk", "cprompt", "chref", "cfunction", "isort", "ilevel", "crole", "objective", "cexec", "jscript", "lparent", "chtml", "jqclass", "class", "private") VALUES ('101199', '100718', 'Browse Widgets FOM', '', '', '90', '0', '', NULL, NULL, 'fetch(''/checkLogin'')
    .then(r => r.json())
    .then(data => {
      if (!data.loggedIn) {
        window.location.href = ''/login.html'';
      } else {
        initPage();
      }
    })
    .catch(() => { window.location.href = ''/login.html''; });

  function initPage() {
 
   let allWidgets = [];
    let currentEditId = null;

    const tabs = document.querySelectorAll(''.w-tab'');
    const paneList = document.getElementById(''w-pane-list'');
    const paneForm = document.getElementById(''w-pane-form'');
    const searchInput = document.getElementById(''w-search'');
    const countSpan = document.getElementById(''w-count'');
    const gridDiv = document.getElementById(''w-grid'');
    const addBtn = document.getElementById(''w-add-btn'');
    const saveBtn = document.getElementById(''w-save-btn'');
    const deleteBtn = document.getElementById(''w-delete-btn'');
    const cancelBtn = document.getElementById(''w-cancel-btn'');
    const formTitle = document.getElementById(''w-form-title'');
    const formStatus = document.getElementById(''w-form-status'');
    const fId = document.getElementById(''f-id'');
    const fChead = document.getElementById(''f-chead'');
    const fCbody = document.getElementById(''f-cbody'');
    const fIgroup = document.getElementById(''f-igroup'');
    const fJscript = document.getElementById(''f-jscript'');

    // Tab switching
    tabs.forEach(tab => {
      tab.addEventListener(''click'', () => {
        tabs.forEach(t => t.classList.remove(''active''));
        tab.classList.add(''active'');
        paneList.style.display = tab.dataset.tab === ''list'' ? ''block'' : ''none'';
        paneForm.style.display = tab.dataset.tab === ''form'' ? ''block'' : ''none'';
        if (tab.dataset.tab === ''list'') {
          searchInput.value = '''';
          renderTable(allWidgets);
        }
      });
    });

    // Load widgets list
    async function loadWidgets() {
      try {
        const resp = await fetch(''/getTable?name=widgets'');
        if (!resp.ok) throw new Error(`HTTP ${resp.status}`);
        const data = await resp.json();
        // Handle both array and {columns, rows} responses
        allWidgets = Array.isArray(data) ? data : (data.rows || []);
        renderTable(allWidgets);
      } catch (err) {
        gridDiv.innerHTML = `<p style="color:red">Error: ${err.message}</p>`;
      }
    }

    // Render table
    function renderTable(widgets) {
      if (!widgets || !widgets.length) {
        gridDiv.innerHTML = ''<p style="color:#aaa">No widgets found.</p>'';
        countSpan.textContent = '''';
        return;
      }
      countSpan.textContent = `(${widgets.length} total)`;
      const cols = [''id'', ''chead'', ''cbody'', ''igroup'', ''jscript''];
      let html = ''<table><thead><tr>'';
      cols.forEach(col => {
        html += `<th>${col}</th>`;
      });
      html += ''<th style="width:100px">Actions</th></tr></thead><tbody>'';
      widgets.forEach(w => {
        html += ''<tr>'';
        cols.forEach(col => {
          let val = w[col] || '''';
          if (col === ''cbody'' || col === ''jscript'') {
            val = (String(val).substring(0, 50) + (String(val).length > 50 ? ''…'' : ''''));
          }
          html += `<td>${escapeHtml(val)}</td>`;
        });
        html += `<td>
          <button class="w-btn w-btn-edit" onclick="window.editWidget(${w.id})">Edit</button>
          <button class="w-btn w-btn-delete" onclick="window.deleteWidgetConfirm(${w.id})">Del</button>
        </td></tr>`;
      });
      html += ''</tbody></table>'';
      gridDiv.innerHTML = html;
    }

    // Search filter
    searchInput.addEventListener(''input'', (e) => {
      const query = e.target.value.toLowerCase();
      if (!query) {
        renderTable(allWidgets);
        return;
      }
      const filtered = allWidgets.filter(w =>
        (w.chead && w.chead.toLowerCase().includes(query)) ||
        (w.cbody && w.cbody.toLowerCase().includes(query)) ||
        (w.id && String(w.id).includes(query))
      );
      renderTable(filtered);
    });

    // Add new widget
    addBtn.addEventListener(''click'', () => {
      currentEditId = null;
      fId.value = '''';
      fChead.value = '''';
      fCbody.value = '''';
      fIgroup.value = 0;
      fJscript.value = '''';
      formTitle.textContent = ''New Widget'';
      deleteBtn.style.display = ''none'';
      formStatus.textContent = '''';
      tabs[1].click();
    });

    // Edit widget
    window.editWidget = async (id) => {
      try {
        const resp = await fetch(`/widget/${id}`);
        if (!resp.ok) throw new Error(`HTTP ${resp.status}`);
        const w = await resp.json();
        currentEditId = id;
        fId.value = w.id;
        fChead.value = w.chead || '''';
        fCbody.value = w.cbody || '''';
        fIgroup.value = w.igroup || 0;
        fJscript.value = w.jscript || '''';
        formTitle.textContent = `Edit Widget #${id}`;
        deleteBtn.style.display = ''inline-block'';
        formStatus.textContent = '''';
        tabs[1].click();
      } catch (err) {
        formStatus.textContent = `Error: ${err.message}`;
        formStatus.style.color = ''red'';
      }
    };

    // Save widget
    saveBtn.addEventListener(''click'', async () => {
      const payload = {
        chead: fChead.value.trim(),
        cbody: fCbody.value.trim(),
        igroup: parseInt(fIgroup.value, 10) || 0,
        jscript: fJscript.value.trim()
      };

      formStatus.textContent = ''Saving…'';
      formStatus.style.color = ''#888'';

      try {
        if (currentEditId) {
          const resp = await fetch(`/widget/${currentEditId}`, {
            method: ''PUT'',
            headers: { ''Content-Type'': ''application/json'' },
            body: JSON.stringify(payload)
          });
          if (!resp.ok) throw new Error(`HTTP ${resp.status}`);
        } else {
          // Create new widget via INSERT
          const resp = await fetch(''/widget'', {
            method: ''POST'',
            headers: { ''Content-Type'': ''application/json'' },
            body: JSON.stringify(payload)
          });
          if (!resp.ok) throw new Error(`HTTP ${resp.status}`);
        }
        formStatus.textContent = ''Saved!'';
        formStatus.style.color = ''#2e7d32'';
        setTimeout(() => { tabs[0].click(); loadWidgets(); }, 800);
      } catch (err) {
        formStatus.textContent = `Error: ${err.message}`;
        formStatus.style.color = ''red'';
      }
    });

    // Delete widget
    window.deleteWidgetConfirm = async (id) => {
      if (!confirm(`Delete widget ${id}? This cannot be undone.`)) return;
      currentEditId = id;
      formStatus.textContent = ''Deleting…'';
      formStatus.style.color = ''#888'';
      try {
        const resp = await fetch(`/widget/${id}`, { method: ''DELETE'' });
        if (!resp.ok) throw new Error(`HTTP ${resp.status}`);
        formStatus.textContent = ''Deleted!'';
        formStatus.style.color = ''#2e7d32'';
        setTimeout(() => { tabs[0].click(); loadWidgets(); }, 800);
      } catch (err) {
        formStatus.textContent = `Error: ${err.message}`;
        formStatus.style.color = ''red'';
      }
    };

    // Cancel
    cancelBtn.addEventListener(''click'', () => {
      tabs[0].click();
    });

    // Helper
    function escapeHtml(text) {
      const map = { ''&'': ''&amp;'', ''<'': ''&lt;'', ''>'': ''&gt;'', ''"'': ''&quot;'', "''": ''&#039;'' };
      return String(text).replace(/[&<>"'']/g, m => map[m]);
    }

    // Load on init
    loadWidgets();
  }

', NULL, '<style>
  #w-wrap { font-family: Arial, sans-serif; font-size: 13px; padding: 10px; }
