      <input id="w-search" type="text" placeholder="Search header or body…">
      <span id="w-count"></span>
      <button class="w-btn w-btn-add" id="w-add-btn">+ Add Widget</button>
    </div>
    <div id="w-grid"><p style="color:#aaa">Loading…</p></div>
  </div>

  <!-- FORM -->
  <div id="w-pane-form" style="display:none">
