INSERT INTO "public"."fommenu" ("pk", "parentpk", "cprompt", "chref", "cfunction", "isort", "ilevel", "crole", "objective", "cexec", "jscript", "lparent", "chtml", "jqclass", "class", "private") VALUES ('101212', '1', 'Upload Photos', 'UploadPhotos.html', '', '30', '0', '', NULL, NULL, '
    var form = document.getElementById(''uploadPhotosForm'');
    var fileInput = document.getElementById(''photoFiles'');
    var preview = document.getElementById(''photoPreview'');
    var statusEl = document.getElementById(''uploadPhotosStatus'');

    fileInput.addEventListener(''change'', function () {
      preview.innerHTML = '''';
      Array.from(fileInput.files).forEach(function (f) {
        if (!f.type.startsWith(''image/'')) return;
        var url = URL.createObjectURL(f);
        var img = document.createElement(''img'');
        img.src = url;
        img.title = f.name + '' ('' + Math.round(f.size / 1024) + '' KB)'';
        img.style.cssText =
          ''width:90px;height:90px;object-fit:cover;border:1px solid #ccc;border-radius:3px'';
        preview.appendChild(img);
      });
    });

    form.addEventListener(''reset'', function () {
      preview.innerHTML = '''';
      statusEl.textContent = '''';
    });

    form.addEventListener(''submit'', function (e) {
      e.preventDefault();
      if (!fileInput.files.length) {
        statusEl.style.color = ''#c0392b'';
        statusEl.textContent = ''Please select at least one photo.'';
        return;
      }
      var fd = new FormData(form);
      statusEl.style.color = ''#888'';
      statusEl.textContent = ''Uploading '' + fileInput.files.length + '' file(s)…'';

      fetch(''/uploadPhotos'', { method: ''POST'', body: fd })
        .then(function (r) {
          return r.json().catch(function () {
            return { ok: r.ok };
          });
        })
        .then(function (data) {
          if (data && data.ok !== false) {
            statusEl.style.color = ''#27ae60'';
            statusEl.textContent =
              ''Uploaded '' +
              (data.count || fileInput.files.length) +
              '' photo(s) successfully.'';
            form.reset();
            preview.innerHTML = '''';
          } else {
            statusEl.style.color = ''#c0392b'';
            statusEl.textContent =
              ''Upload failed'' + (data && data.error ? '': '' + data.error : ''.'');
          }
        })
        .catch(function (err) {
          statusEl.style.color = ''#c0392b'';
          statusEl.textContent = ''Upload error: '' + err.message;
        });
    });', NULL, '', 'fom-lc', NULL, NULL);
INSERT INTO "public"."fommenu" ("pk", "parentpk", "cprompt", "chref", "cfunction", "isort", "ilevel", "crole", "objective", "cexec", "jscript", "lparent", "chtml", "jqclass", "class", "private") VALUES ('101215', '1', 'Send Email — Raw SQL', 'sendemail-raw.html', '', '998', '0', 'd', NULL, NULL, '
      const $ = (id) => document.getElementById(id);
      let lastRows = [];
      let currentCampaignId = null;

      const setStatus = (msg, cls = '''') => {
        const el = $(''status'');
        el.textContent = msg;
        el.className = cls;
      };

      async function loadCampaigns() {
        const r = await fetch(''/api/sendemail/list?qtype=raw'');
        const data = await r.json();
        if (!r.ok) {
          setStatus(data.error || `HTTP ${r.status}`, ''err'');
          return;
        }
        const sel = $(''campaign'');
        sel.innerHTML = ''<option value="">— New campaign —</option>'';
        for (const c of data) {
          const opt = document.createElement(''option'');
          opt.value = c.id;
          opt.textContent = c.name;
          sel.appendChild(opt);
        }
      }

      async function loadCampaign(id) {
        currentCampaignId = id || null;
        $(''btn-delete'').disabled = !id;
        $(''result-section'').classList.add(''hidden'');
        if (!id) {
          $(''name'').value = '''';
          $(''sql-input'').value = '''';
          $(''letter-input'').value = '''';
          return;
        }
        const r = await fetch(''/api/sendemail/recipients'', {
          method: ''POST'',
          headers: { ''Content-Type'': ''application/json'' },
          body: JSON.stringify({ id }),
        });
        // We use this only for the campaign''s name/letter; we''ll fetch full row via list next time.
        // Simpler: hit list and find the row.
        const listResp = await fetch(''/api/sendemail/list?qtype=raw'');
        const list = await listResp.json();
        const row = list.find((c) => String(c.id) === String(id));
        if (row) $(''name'').value = row.name;
        // We don''t currently expose query/letter via /list — re-fetch via a single-row call.
        // Cheap workaround: stash on the option.
      }

      // Cache full row data for editing — fetch all rows including query+letter on load.
      let rawRows = [];
      async function refreshRawList() {
        const r = await fetch(''/api/sendemail/list?qtype=raw'');
        const data = await r.json();
        if (!r.ok) {
          setStatus(data.error || `HTTP ${r.status}`, ''err'');
          return;
        }
        rawRows = data;
        const sel = $(''campaign'');
        const cur = sel.value;
        sel.innerHTML = ''<option value="">— New campaign —</option>'';
        for (const c of data) {
          const opt = document.createElement(''option'');
          opt.value = c.id;
          opt.textContent = c.name;
          sel.appendChild(opt);
        }
        sel.value = cur;
      }

      $(''campaign'').addEventListener(''change'', async () => {
        const id = $(''campaign'').value;
        currentCampaignId = id || null;
        $(''btn-delete'').disabled = !id;
        $(''result-section'').classList.add(''hidden'');
        if (!id) {
          $(''name'').value = '''';
          $(''sql-input'').value = '''';
          $(''letter-input'').value = '''';
          return;
        }
        // Pull full record via the recipients endpoint (returns letter); for SQL, we need to fetch separately.
        // Simpler: ask the server for the row directly. We''ll piggyback: list returns minimal fields; full
        // row fetched by running the query is heavy. Add a tiny inline GET via /recipients which echoes letter.
        const found = rawRows.find((r) => String(r.id) === String(id));
        $(''name'').value = found?.name || '''';
        // Fetch the row''s query+letter via /recipients (returns letter; query is server-only). For editing,
        // use the dedicated /load endpoint we''ll add inline below as a fallback: try /api/sendemail/load.
        try {
          const r = await fetch(
            ''/api/sendemail/load?id='' + encodeURIComponent(id),
          );
          if (r.ok) {
            const data = await r.json();
            $(''sql-input'').value = data.query || '''';
            $(''letter-input'').value = data.letter || '''';
          }
        } catch {}
      });

      $(''btn-new'').addEventListener(''click'', () => {
        $(''campaign'').value = '''';
        currentCampaignId = null;
        $(''btn-delete'').disabled = true;
        $(''name'').value = '''';
        $(''sql-input'').value = '''';
        $(''letter-input'').value = '''';
        $(''result-section'').classList.add(''hidden'');
        setStatus('''');
      });

      $(''btn-save'').addEventListener(''click'', async () => {
        const payload = {
          id: currentCampaignId || undefined,
          name: $(''name'').value.trim(),
          qtype: ''raw'',
          query: $(''sql-input'').value.trim(),
          letter: $(''letter-input'').value,
        };
        if (!payload.name || !payload.query) {
          setStatus(''Name and SQL are required.'', ''err'');
          return;
        }
        setStatus(''Saving…'');
        const r = await fetch(''/api/sendemail/save'', {
          method: ''POST'',
          headers: { ''Content-Type'': ''application/json'' },
          body: JSON.stringify(payload),
        });
        const data = await r.json();
        if (data.error) {
          setStatus(data.error, ''err'');
          return;
        }
        currentCampaignId = data.id;
        setStatus(''Saved.'', ''ok'');
        await refreshRawList();
        $(''campaign'').value = String(data.id);
        $(''btn-delete'').disabled = false;
      });

      $(''btn-delete'').addEventListener(''click'', async () => {
        if (!currentCampaignId) return;
        if (!confirm(''Delete this campaign?'')) return;
        const r = await fetch(''/api/sendemail/delete'', {
          method: ''POST'',
          headers: { ''Content-Type'': ''application/json'' },
          body: JSON.stringify({ id: currentCampaignId }),
        });
        const data = await r.json();
        if (data.error) {
          setStatus(data.error, ''err'');
          return;
        }
        currentCampaignId = null;
        $(''btn-delete'').disabled = true;
        $(''name'').value = '''';
        $(''sql-input'').value = '''';
        $(''letter-input'').value = '''';
        $(''result-section'').classList.add(''hidden'');
        await refreshRawList();
        setStatus(''Deleted.'', ''ok'');
      });

      $(''btn-load'').addEventListener(''click'', async () => {
        if (!currentCampaignId) {
          setStatus(''Save the campaign first, then Load Recipients.'', ''err'');
          return;
        }
        setStatus(''Running query…'');
        const r = await fetch(''/api/sendemail/recipients'', {
          method: ''POST'',
          headers: { ''Content-Type'': ''application/json'' },
          body: JSON.stringify({ id: currentCampaignId }),
        });
        const data = await r.json();
        if (data.error) {
          setStatus(data.error, ''err'');
          return;
        }
        lastRows = data.rows;
        $(''count'').textContent = data.count;
        $(''preview'').innerHTML =
          data.preview || ''<i>(no recipients — preview empty)</i>'';
        $(''result-section'').classList.remove(''hidden'');
        $(''list-panel'').classList.add(''hidden'');
        setStatus('''');
      });

      function renderList() {
        const cols = lastRows.length ? Object.keys(lastRows[0]) : [''email''];
        const thead =
          ''<tr><th><input type="checkbox" id="hdr-check" checked></th>'' +
          cols.map((c) => `<th>${c}</th>`).join('''') +
          ''</tr>'';
        const tbody = lastRows
          .map(
            (row) =>
              `<tr><td><input type="checkbox" class="rcpt" data-email="${row.email}" checked></td>` +
              cols
                .map(
                  (c) =>
                    `<td>${row[c] == null ? '''' : String(row[c]).replace(/[<>&]/g, (s) => ({ ''<'': ''&lt;'', ''>'': ''&gt;'', ''&'': ''&amp;'' })[s])}</td>`,
                )
                .join('''') +
              ''</tr>'',
          )
          .join('''');
        $(''recipients-table'').querySelector(''thead'').innerHTML = thead;
        $(''recipients-table'').querySelector(''tbody'').innerHTML = tbody;
        $(''hdr-check'').addEventListener(''change'', (e) => {
          document
            .querySelectorAll(''.rcpt'')
            .forEach((cb) => (cb.checked = e.target.checked));
          updateCheckedCount();
        });
        document
          .querySelectorAll(''.rcpt'')
          .forEach((cb) => cb.addEventListener(''change'', updateCheckedCount));
        updateCheckedCount();
      }
      function updateCheckedCount() {
        const n = document.querySelectorAll(''.rcpt:checked'').length;
        $(''checked-count'').textContent = `${n} of ${lastRows.length} checked`;
      }
      function getCheckedEmails() {
        return Array.from(document.querySelectorAll(''.rcpt:checked'')).map(
          (cb) => cb.dataset.email,
        );
      }

      $(''btn-view-list'').addEventListener(''click'', () => {
        renderList();
        $(''list-panel'').classList.remove(''hidden'');
      });
      $(''btn-check-all'').addEventListener(''click'', () => {
        document.querySelectorAll(''.rcpt'').forEach((cb) => (cb.checked = true));
        $(''hdr-check'').checked = true;
        updateCheckedCount();
      });
      $(''btn-check-none'').addEventListener(''click'', () => {
        document
          .querySelectorAll(''.rcpt'')
          .forEach((cb) => (cb.checked = false));
        $(''hdr-check'').checked = false;
        updateCheckedCount();
      });

      $(''btn-test'').addEventListener(''click'', async () => {
        setStatus(''Sending test…'');
        const r = await fetch(''/api/sendemail/test'', {
          method: ''POST'',
          headers: { ''Content-Type'': ''application/json'' },
          body: JSON.stringify({ id: currentCampaignId }),
        });
        const data = await r.json();
        setStatus(
          data.error ? data.error : `Test sent to ${data.sentTo}`,
          data.error ? ''err'' : ''ok'',
        );
      });
      $(''btn-cancel'').addEventListener(''click'', () => {
        $(''result-section'').classList.add(''hidden'');
        setStatus(''Canceled.'');
      });
      $(''btn-transmit'').addEventListener(''click'', async () => {
        const emails = $(''list-panel'').classList.contains(''hidden'')
          ? lastRows.map((r) => r.email)
          : getCheckedEmails();
        if (!emails.length) {
          setStatus(''No recipients selected.'', ''err'');
          return;
        }
        if (!confirm(`Send to ${emails.length} recipient(s)?`)) return;
        setStatus(''Transmitting…'');
        const r = await fetch(''/api/sendemail/transmit'', {
          method: ''POST'',
          headers: { ''Content-Type'': ''application/json'' },
          body: JSON.stringify({ id: currentCampaignId, emails }),
        });
        const data = await r.json();
        if (data.error) {
          setStatus(data.error, ''err'');
          return;
        }
        setStatus(
          `Sent ${data.sent} of ${data.attempted}` +
            (data.errors.length ? ` — ${data.errors.length} failures` : ''''),
          ''ok'',
        );
      });

      refreshRawList();
    ', NULL, '', 'fom-lc', NULL, NULL);
INSERT INTO "public"."fommenu" ("pk", "parentpk", "cprompt", "chref", "cfunction", "isort", "ilevel", "crole", "objective", "cexec", "jscript", "lparent", "chtml", "jqclass", "class", "private") VALUES ('101216', '1', 'Send Email', 'sendemail.html', '', '999', '0', '', NULL, NULL, '
      const $ = (id) => document.getElementById(id);
      let lastRows = [];
      let currentCampaignId = null;

      const setStatus = (msg, cls = '''') => {
        const el = $(''status'');
        el.textContent = msg;
        el.className = cls;
      };

      async function loadCampaigns() {
        const r = await fetch(''/api/sendemail/list?qtype=saved'');
        const list = await r.json();
        const sel = $(''campaign'');
        sel.innerHTML = ''<option value="">— pick a campaign —</option>'';
        for (const c of list) {
          const opt = document.createElement(''option'');
          opt.value = c.id;
          opt.textContent = c.name;
          sel.appendChild(opt);
        }
      }

      async function loadRecipients() {
        const id = $(''campaign'').value;
        if (!id) return;
        currentCampaignId = id;
        setStatus(''Running query…'');
        $(''result-section'').classList.add(''hidden'');
        const r = await fetch(''/api/sendemail/recipients'', {
          method: ''POST'',
          headers: { ''Content-Type'': ''application/json'' },
          body: JSON.stringify({ id }),
        });
        const data = await r.json();
        if (data.error) {
          setStatus(data.error, ''err'');
          return;
        }
        lastRows = data.rows;
        $(''count'').textContent = data.count;
        $(''preview'').innerHTML =
          data.preview || ''<i>(no recipients — preview empty)</i>'';
        $(''result-section'').classList.remove(''hidden'');
        $(''list-panel'').classList.add(''hidden'');
        setStatus('''');
      }

      function renderList() {
        const cols = lastRows.length ? Object.keys(lastRows[0]) : [''email''];
        const thead =
          ''<tr><th><input type="checkbox" id="hdr-check" checked></th>'' +
          cols.map((c) => `<th>${c}</th>`).join('''') +
          ''</tr>'';
        const tbody = lastRows
          .map(
            (row, i) =>
              `<tr><td><input type="checkbox" class="rcpt" data-email="${row.email}" checked></td>` +
              cols
                .map(
                  (c) =>
                    `<td>${row[c] == null ? '''' : String(row[c]).replace(/[<>&]/g, (s) => ({ ''<'': ''&lt;'', ''>'': ''&gt;'', ''&'': ''&amp;'' })[s])}</td>`,
                )
                .join('''') +
              ''</tr>'',
          )
          .join('''');
        $(''recipients-table'').querySelector(''thead'').innerHTML = thead;
        $(''recipients-table'').querySelector(''tbody'').innerHTML = tbody;
        $(''hdr-check'').addEventListener(''change'', (e) => {
          document
            .querySelectorAll(''.rcpt'')
            .forEach((cb) => (cb.checked = e.target.checked));
          updateCheckedCount();
        });
        document
          .querySelectorAll(''.rcpt'')
          .forEach((cb) => cb.addEventListener(''change'', updateCheckedCount));
        updateCheckedCount();
      }

      function updateCheckedCount() {
        const n = document.querySelectorAll(''.rcpt:checked'').length;
        $(''checked-count'').textContent = `${n} of ${lastRows.length} checked`;
      }

      function getCheckedEmails() {
        return Array.from(document.querySelectorAll(''.rcpt:checked'')).map(
          (cb) => cb.dataset.email,
        );
      }

      $(''campaign'').addEventListener(''change'', () => {
        $(''btn-load'').disabled = !$(''campaign'').value;
      });
      $(''btn-load'').addEventListener(''click'', loadRecipients);

      $(''btn-view-list'').addEventListener(''click'', () => {
        renderList();
        $(''list-panel'').classList.remove(''hidden'');
      });

      $(''btn-check-all'').addEventListener(''click'', () => {
        document.querySelectorAll(''.rcpt'').forEach((cb) => (cb.checked = true));
        $(''hdr-check'').checked = true;
        updateCheckedCount();
      });
      $(''btn-check-none'').addEventListener(''click'', () => {
        document
          .querySelectorAll(''.rcpt'')
          .forEach((cb) => (cb.checked = false));
        $(''hdr-check'').checked = false;
        updateCheckedCount();
      });

      $(''btn-test'').addEventListener(''click'', async () => {
        setStatus(''Sending test…'');
        const r = await fetch(''/api/sendemail/test'', {
          method: ''POST'',
          headers: { ''Content-Type'': ''application/json'' },
          body: JSON.stringify({ id: currentCampaignId }),
        });
        const data = await r.json();
        setStatus(
          data.error ? data.error : `Test sent to ${data.sentTo}`,
          data.error ? ''err'' : ''ok'',
        );
      });

      $(''btn-cancel'').addEventListener(''click'', () => {
        $(''result-section'').classList.add(''hidden'');
        $(''campaign'').value = '''';
        $(''btn-load'').disabled = true;
        setStatus(''Canceled.'');
      });

      $(''btn-transmit'').addEventListener(''click'', async () => {
        const emails = $(''list-panel'').classList.contains(''hidden'')
          ? lastRows.map((r) => r.email)
          : getCheckedEmails();
        if (!emails.length) {
          setStatus(''No recipients selected.'', ''err'');
          return;
        }
        if (!confirm(`Send to ${emails.length} recipient(s)?`)) return;
        setStatus(''Transmitting…'');
        const r = await fetch(''/api/sendemail/transmit'', {
          method: ''POST'',
          headers: { ''Content-Type'': ''application/json'' },
          body: JSON.stringify({ id: currentCampaignId, emails }),
        });
        const data = await r.json();
        if (data.error) {
          setStatus(data.error, ''err'');
          return;
        }
        setStatus(
          `Sent ${data.sent} of ${data.attempted}` +
            (data.errors.length ? ` — ${data.errors.length} failures` : ''''),
          ''ok'',
        );
      });

      loadCampaigns();
    ', NULL, '', 'fom-lc', NULL, NULL);
INSERT INTO "public"."fommenu" ("pk", "parentpk", "cprompt", "chref", "cfunction", "isort", "ilevel", "crole", "objective", "cexec", "jscript", "lparent", "chtml", "jqclass", "class", "private") VALUES ('101217', '1', 'sqlquery', 'sqlquery.html', '', '110', '0', '', NULL, NULL, '
  (function() {
    var history = [];

    function esc(v) {
      return String(v == null ? '''' : v)
        .replace(/&/g,''&amp;'').replace(/</g,''&lt;'').replace(/>/g,''&gt;'').replace(/"/g,''&quot;'');
    }

    function setStatus(msg, color) {
      var el = document.getElementById(''status'');
      el.textContent = msg;
      el.style.color = color || ''#888'';
    }

    function run() {
      var sql = document.getElementById(''sql-input'').value.trim();
      if (!sql) return;
      setStatus(''Running…'', ''#888'');
      document.getElementById(''results-wrap'').innerHTML = '''';

      fetch(''/runQuery'', {
        method: ''POST'',
        headers: { ''Content-Type'': ''application/json'' },
        body: JSON.stringify({ sql: sql })
      })
      .then(function(r) { return r.json(); })
      .then(function(res) {
        if (res.error) {
          document.getElementById(''results-wrap'').innerHTML = ''<div id="error-msg">'' + esc(res.error) + ''</div>'';
          setStatus(''Error'', ''#c62828'');
          return;
        }
        addHistory(sql);
        var rowWord = res.rowCount === 1 ? ''row'' : ''rows'';
        if (!res.columns || res.columns.length === 0) {
          setStatus(res.rowCount + '' '' + rowWord + '' affected  ('' + res.ms + '' ms)'', ''#2e7d32'');
          return;
        }
        setStatus(res.rows.length + '' '' + rowWord + ''  ('' + res.ms + '' ms)'', ''#2e7d32'');
        var html = ''<table><thead><tr>'';
        res.columns.forEach(function(c) { html += ''<th>'' + esc(c) + ''</th>''; });
        html += ''</tr></thead><tbody>'';
        res.rows.forEach(function(r) {
          html += ''<tr>'';
          res.columns.forEach(function(c) {
            var v = r[c];
            if (v !== null && typeof v === ''object'') v = JSON.stringify(v);
            html += ''<td>'' + esc(v) + ''</td>'';
          });
          html += ''</tr>'';
        });
        html += ''</tbody></table>'';
        document.getElementById(''results-wrap'').innerHTML = html;
      })
      .catch(function(err) { setStatus(''Request failed: '' + err.message, ''#c62828''); });
    }

    function addHistory(sql) {
      history = [sql].concat(history.filter(function(s) { return s !== sql; })).slice(0, 20);
      var html = history.map(function(s) {
        return ''<div class="hist-item" title="'' + esc(s) + ''">'' + esc(s) + ''</div>'';
      }).join('''');
      document.getElementById(''history-list'').innerHTML = html;
      document.getElementById(''history-wrap'').style.display = '''';
    }

    document.getElementById(''btn-run'').addEventListener(''click'', run);

    document.getElementById(''btn-clear'').addEventListener(''click'', function() {
      document.getElementById(''sql-input'').value = '''';
      document.getElementById(''sql-input'').focus();
      document.getElementById(''results-wrap'').innerHTML = '''';
      setStatus('''');
    });

    document.getElementById(''sql-input'').addEventListener(''keydown'', function(e) {
      if ((e.ctrlKey || e.metaKey) && e.key === ''Enter'') run();
    });

    document.getElementById(''history-list'').addEventListener(''click'', function(e) {
      var item = e.target.closest(''.hist-item'');
      if (item) {
        document.getElementById(''sql-input'').value = item.getAttribute(''title'');
        run();
      }
    });
  })();
  ', NULL, '', 'fom-lc', NULL, NULL);
