      success: function (response) {
        const totalNonResponders = response.data.length;
        const statsHtml = `
          <div class="stat-card">
            <h3>Non-Responders</h3>
            <div class="value">${totalNonResponders}</div>
          </div>
        `;
        $(''#statsGrid'').html(statsHtml);

        const tableHtml = response.data
