                <td><span class="badge badge-info">${doctor.email_type || ''N/A''}</span></td>
                <td>${doctor.follow_ups_sent || 0}</td>
                <td>${doctor.last_follow_up_at ? new Date(doctor.last_follow_up_at).toLocaleDateString() : ''Never''}</td>
              </tr>
            `,
          )
          .join('''');

        $(''#nonRespondersTable tbody'').html(
          tableHtml ||
            ''<tr><td colspan="5" style="text-align: center; color: #999;">No non-responders</td></tr>'',
        );
      },
      error: function () {
        showAlert(''Failed to load dashboard'', ''error'');
      },
    });
  }

  loadDashboard();
