    l.id = ''doctors-admin-css'';
    l.rel = ''stylesheet'';
    l.href = ''/aaa/doctors/admin.css'';
    document.head.appendChild(l);
  }

  function showAlert(message, type) {
    const alertHtml = `<div class="alert alert-${type}">${message}</div>`;
    $(''#alerts'').append(alertHtml);
    setTimeout(() => {
      $(`#alerts .alert-${type}`).fadeOut(function () {
        $(this).remove();
      });
    }, 5000);
  }

  function escapeHtml(value) {
    if (value === null || value === undefined) return '''';
    return String(value)
      .replace(/&/g, ''&amp;'')
      .replace(/</g, ''&lt;'')
      .replace(/>/g, ''&gt;'')
      .replace(/"/g, ''&quot;'')
      .replace(/''/g, ''&#39;'');
  }

  function loadOffices() {
    const search = $(''#officeSearch'').val();
    const state = $(''#officeStateFilter'').val();

    $.ajax({
      url: ''/api/admin/offices'',
      method: ''GET'',
      data: { search, state },
      success: function (response) {
        const rows = response.data || [];
        const tbody = rows
          .map(
            (o) => `
              <tr>
                <td>${escapeHtml(o.name)}</td>
                <td>${escapeHtml(o.street)}</td>
                <td>${escapeHtml(o.city)}</td>
                <td>${escapeHtml(o.state)}</td>
                <td>${escapeHtml(o.zip)}</td>
                <td>
                  <div class="action-buttons">
                    <button onclick=''editOffice(${o.id})''>Edit</button>
                    <button onclick=''deleteOffice(${o.id})'' class="danger">Delete</button>
                  </div>
                </td>
              </tr>
            `,
          )
          .join('''');

        $(''#officesTable tbody'').html(
          tbody ||
            ''<tr><td colspan="6" style="text-align: center; color: #999;">No offices found</td></tr>'',
        );
      },
      error: function (xhr) {
        const error = xhr.responseJSON?.error || ''Failed to load offices'';
        showAlert(error, ''error'');
      },
    });
  }

  function openOfficeModal(office) {
    $(''#officeModalTitle'').text(office ? ''Edit Office'' : ''Add Office'');
    $(''#officeId'').val(office ? office.id : '''');
    $(''#officeName'').val(office ? office.name : '''');
    $(''#officeStreet'').val(office ? office.street : '''');
    $(''#officeCity'').val(office ? office.city : '''');
    $(''#officeState'').val(office ? office.state : ''DE'');
    $(''#officeZip'').val(office ? office.zip : '''');
    $(''#officeModal'').css(''display'', ''block'');
  }

  function closeOfficeModal() {
    $(''#officeModal'').css(''display'', ''none'');
  }

  function editOffice(id) {
    $.ajax({
      url: `/api/admin/offices/${id}`,
      method: ''GET'',
      success: function (response) {
        openOfficeModal(response.data);
      },
      error: function (xhr) {
        const error = xhr.responseJSON?.error || ''Failed to load office'';
        showAlert(error, ''error'');
      },
    });
  }

  function saveOffice() {
    const id = $(''#officeId'').val();
    const payload = {
      name: $(''#officeName'').val().trim(),
      street: $(''#officeStreet'').val().trim(),
      city: $(''#officeCity'').val().trim(),
      state: $(''#officeState'').val(),
      zip: $(''#officeZip'').val().trim(),
    };

    if (
      !payload.name ||
      !payload.street ||
      !payload.city ||
      !payload.state ||
      !payload.zip
    ) {
      showAlert(''All fields are required'', ''error'');
      return;
    }

    const url = id ? `/api/admin/offices/${id}` : ''/api/admin/offices'';
    const method = id ? ''PUT'' : ''POST'';

    $.ajax({
      url,
      method,
      contentType: ''application/json'',
      data: JSON.stringify(payload),
      success: function () {
        showAlert(id ? ''Office updated'' : ''Office created'', ''success'');
        closeOfficeModal();
        loadOffices();
      },
      error: function (xhr) {
        const error = xhr.responseJSON?.error || ''Failed to save office'';
        showAlert(error, ''error'');
      },
    });
  }

  function deleteOffice(id) {
    if (!confirm(''Are you sure? This will soft-delete the office.'')) return;

    $.ajax({
      url: `/api/admin/offices/${id}`,
      method: ''DELETE'',
      success: function () {
        showAlert(''Office deleted'', ''success'');
        loadOffices();
      },
      error: function (xhr) {
        const error = xhr.responseJSON?.error || ''Failed to delete office'';
        showAlert(error, ''error'');
      },
    });
  }

  $(document).off(''click.officeModal'').on(''click.officeModal'', ''#officeModal'', function (e) {
    if (e.target.id === ''officeModal'') closeOfficeModal();
  });

  $(document).off(''keyup.officeSearch'').on(''keyup.officeSearch'', ''#officeSearch'', function (e) {
    if (e.key === ''Enter'') loadOffices();
  });

  loadOffices();
', NULL, '', 'fom-lc', NULL, NULL);
